const http2 = require('http2');
const fs = require('fs');
const jwt = require('jsonwebtoken');
const { CrmContact, SalesTerritory } = require('../models/crm');

const server = http2.createSecureServer({
  key: fs.readFileSync('/etc/ssl/crm.key'),
  cert: fs.readFileSync('/etc/ssl/crm.crt')
});

server.on('stream', async (stream, headers) => {
  const url = new URL(headers[':path'], 'https://crm.sales.internal');

  if (url.pathname === '/crm/view') {
    const contactId = url.searchParams.get('contactId');

    const authHeader = headers['authorization'];
    if (!authHeader) {
      stream.respond({ ':status': 401 });
      return stream.end('Unauthorized');
    }

    let rep;
    try {
      rep = jwt.verify(authHeader.replace('Bearer ', ''), process.env.JWT_SECRET);
    } catch {
      stream.respond({ ':status': 401 });
      return stream.end('Invalid credentials');
    }

    const contact = await CrmContact.findById(contactId);
    if (!contact) {
      stream.respond({ ':status': 404 });
      return stream.end('Contact not found');
    }

    // Verify account executive has rights to view this enterprise contact
    const hasTerritoryAccess = await SalesTerritory.checkAccess(rep.repId, contact.accountId);
    if (!hasTerritoryAccess) {
      stream.respond({ ':status': 403 });
      return stream.end('Access denied: not authorized for this account territory');
    }

    if (contactId && stream.pushAllowed) {
      stream.pushStream({ ':path': `/api/contacts/${contactId}/deal-notes.json` }, async (err, pushStream) => {
        if (err) return;
        pushStream.respond({ ':status': 200, 'content-type': 'application/json' });
        pushStream.end(JSON.stringify({
          contactId,
          executiveNotes: contact.executiveNotes,
          pipelineValuation: contact.pipelineValuation
        }));
      });
    }

    stream.respond({ ':status': 200, 'content-type': 'text/html' });
    stream.end('<html><body>CRM contact view rendered</body></html>');
  }
});

server.listen(8446);
